context.handlebars.registerHelper('numberFormat', function (value, options) {
  // Helper parameters
  var dl = options.hash['decimalLength'] || 2;
  var ts = options.hash['thousandsSep'] || ',';
  var ds = options.hash['decimalSep'] || '.';

  // Parse to float
  var value = parseFloat(value);

  // The regex
  var re = '\\d(?=(\\d{3})+' + (dl > 0 ? '\\D' : '$') + ')';

  // Formats the number with the decimals
  var num = value.toFixed(Math.max(0, ~~dl));

  // Returns the formatted number
  return (ds ? num.replace('.', ds) : num).replace(new RegExp(re, 'g'), '$&' + ts);
});



// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

options.styles:
.plant-status-kpi-wrap {
  font-family: var(--font-sans, Inter, Arial, sans-serif);
  color: var(--color-text-primary, #1f2933);
}
.plant-status-kpi-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}
.plant-status-kpi-title {
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.3px;
  text-transform: uppercase;
}

.plant-status-kpi-note {
  color: var(--color-text-secondary, #667085);
  font-size: 13px;
  white-space: nowrap;
}

.plant-status-kpi-freshness {
  font-size: 13px;
  color: var(--color-text-secondary, #667085);
}
.plant-status-kpi-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(143px, 1fr));
  gap: 10px;
}
.plant-status-kpi-card {
  position: relative;
  min-height: 101px;
  padding: 12px 13px;
  border: 0.5px solid var(--color-border-tertiary, #d0d5dd);
  border-radius: 6px;
  background: #fff;
}
.plant-status-kpi-icon {
  position: absolute;
  top: 13px;
  left: 13px;
  color: var(--color-text-secondary, #667085);
  font-size: 14px;
  line-height: 1;
}
.plant-status-kpi-label {
  padding-left: 22px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.3px;
  color: var(--color-text-secondary, #667085);
  text-transform: uppercase;
}
.plant-status-kpi-value {
  margin-top: 7px;
  font-size: 26px;
  font-weight: 600;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.plant-status-kpi-unit {
  font-size: 13px;
  font-weight: 400;
  color: var(--color-text-secondary, #667085);
}
.plant-status-kpi-sub {
  margin-top: 5px;
  font-size: 13px;
  color: var(--color-text-secondary, #667085);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.plant-status-kpi-good .plant-status-kpi-value { color: #548235; }
.plant-status-kpi-warn .plant-status-kpi-value { color: #bf8f00; }
.plant-status-kpi-bad .plant-status-kpi-value { color: #c00000; }
.plant-status-kpi-neutral .plant-status-kpi-value { color: #2f75b5; }

@media (max-width: 1280px) {
  .plant-status-kpi-grid {
    grid-template-columns: repeat(3, minmax(169px, 1fr));
  }
}

@media (max-width: 720px) {
  .plant-status-kpi-grid {
    grid-template-columns: repeat(2, minmax(156px, 1fr));
  }
}

/* ---------- Dark theme (only applies when Grafana is in dark mode) ---------- */
.plant-status-kpi-wrap:where(.dark) {
  color: var(--color-text-primary, #e4e4ec);
}
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-freshness,
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-note,
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-icon,
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-label,
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-unit,
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-sub {
  color: var(--color-text-secondary, #b0b0be);
}
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-card {
  border-color: var(--color-border-tertiary, #34373d);
  background: #181b1f;
}
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-good .plant-status-kpi-value { color: #73bf69; }
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-warn .plant-status-kpi-value { color: #f2cc0c; }
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-bad .plant-status-kpi-value { color: #ff7383; }
*:where(.plant-status-kpi-wrap.dark) .plant-status-kpi-neutral .plant-status-kpi-value { color: #8ab8ff; }

spec.query:
import "date"
import "timezone"

// Set the global location context
option location = timezone.location(name: "Asia/Kuala_Lumpur")

from(bucket: "cpms")
    |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
    |> filter(fn: (r) => r._measurement == "chiller")
    |> filter(fn: (r) => r._field == "estimatedLoadRt")
    |> integral(unit: 1h)
    |> group()
    |> sum()
    |> map(fn: (r) => ({
        r with coolingLoad: r._value,
        coolingCapacity: r._value * ${RT_TO_KW}
    }))

import "date"
import "timezone"

// Set the global location context
option location = timezone.location(name: "Asia/Kuala_Lumpur")

from(bucket: "cpms")
    |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
    |> filter(fn: (r) => r._measurement == "power")
    |> filter(fn: (r) => r.deviceId == "main")
    |> filter(fn: (r) => r._field == "energyUsage")
    |> sum()
    |> map(fn: (r) => ({
        r with energyUsage: r._value
    }))

