  };
  const fallbackColors = ['#4f9fe6', '#9b7fea', '#2ec4b6', '#7088e8', '#e59f3a'];
  const displayName = (deviceId) => {
    const match = deviceId.match(/^(chiller|ct|chwp|cwp)[-_ ]?(\d+)$/i);
    if (!match) return deviceId.toUpperCase();
    const prefix = match[1].toLowerCase() === 'chiller' ? 'CH' : match[1].toUpperCase();
    return `${prefix}-${match[2].padStart(2, '0')}`;
  };
  const groupKey = (type) => type.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const cell = (text, className) => {
    const node = document.createElement('td');
    if (className) node.className = className;
    node.textContent = text;
    return node;
  };
  const measurementCell = (value, digits, unit) => {
    if (value === null || !Number.isFinite(value)) return cell('—');
    const node = document.createElement('td');
    const reading = document.createElement('span');
    const suffix = document.createElement('span');
    reading.className = 'plant-efficiency-breakdown-value';
    suffix.className = 'plant-efficiency-breakdown-unit';
    reading.textContent = value.toFixed(digits);
    suffix.textContent = unit;
    node.append(reading, suffix);
    return node;
  };
  const groups = [...devices.reduce((map, device) => {
    const key = groupKey(device.type);
    const group = map.get(key) || {
      key,
      type: device.type,
      label: typeNames[device.type.toLowerCase()] || device.type,
      sortOrder: device.sortOrder,
      devices: [],
    };
    group.sortOrder = Math.min(group.sortOrder, device.sortOrder);
    group.devices.push(device);
    map.set(key, group);
    return map;
  }, new Map()).values()].sort((a, b) => a.sortOrder - b.sortOrder || a.label.localeCompare(b.label));
  groups.forEach((group, index) => {
    group.subtotal = group.devices.reduce((total, device) => total + device.power, 0);
    group.color = typeColors[group.type.toLowerCase()] || fallbackColors[index % fallbackColors.length];
  });

  const chartUsesMainMeter = validPlantPower && plantPower >= submeterPower;
  const chartTotal = chartUsesMainMeter ? plantPower : submeterPower;
  const chartItems = groups.map((group) => ({
    label: group.label,
    power: group.subtotal,
    color: group.color,
  }));
  if (chartUsesMainMeter && plantPower > submeterPower) {
    chartItems.push({
      label: 'Unallocated / Estimated Auxiliary',
      power: plantPower - submeterPower,
      color: '#b565a7',
    });
  }
  const chartDescription = chartItems
    .filter((item) => item.power > 0)
    .map((item) => `${item.label} ${(item.power / chartTotal * 100).toFixed(1)}%`)
    .join(', ');
  const chartSegments = document.createDocumentFragment();
  const legendItems = document.createDocumentFragment();
  chartItems.forEach((item) => {
    const share = chartTotal > 0 ? item.power / chartTotal * 100 : 0;
    if (item.power > 0) {
      const segment = document.createElement('span');
      segment.className = 'plant-efficiency-breakdown-chart-segment';
      segment.style.width = `${share}%`;
      segment.style.backgroundColor = item.color;
      segment.title = `${item.label}: ${item.power.toFixed(1)} kW (${share.toFixed(1)}%)`;
      chartSegments.append(segment);
    }
    const legendItem = document.createElement('span');
    const swatch = document.createElement('span');
    const label = document.createElement('span');
    legendItem.className = 'plant-efficiency-breakdown-chart-legend-item';
    swatch.className = 'plant-efficiency-breakdown-chart-swatch';
    swatch.style.backgroundColor = item.color;
    label.textContent = `${item.label} · ${item.power.toFixed(1)} kW · ${share.toFixed(1)}%`;
    legendItem.append(swatch, label);
    legendItems.append(legendItem);
  });
  chartBar.replaceChildren(chartSegments);
  chartBar.setAttribute('aria-label', `Power breakdown: ${chartDescription}`);
  chartLegend.replaceChildren(legendItems);
  chartNote.textContent = chartUsesMainMeter ? 'Share of main plant power' : 'Share of submetered power';

  const fragment = document.createDocumentFragment();
  groups.forEach((group) => {
    group.devices.sort((a, b) => a.deviceId.localeCompare(b.deviceId, undefined, { numeric: true }));
    const subtotal = group.subtotal;
    const heading = document.createElement('tr');
    const labelCell = document.createElement('td');
    const toggle = document.createElement('button');
    heading.className = 'plant-efficiency-breakdown-group';
    labelCell.colSpan = 3;
    toggle.className = 'plant-efficiency-breakdown-toggle';
    toggle.type = 'button';
    toggle.dataset.groupToggle = group.key;
    toggle.setAttribute('aria-expanded', 'true');
    toggle.textContent = group.label;
    labelCell.append(toggle);
    heading.append(
      labelCell,
      measurementCell(subtotal, 1, ' kW'),
      measurementCell(validCoolingLoad ? subtotal / coolingLoad : null, 4, ' kW/RT'),
      measurementCell(validPlantPower ? subtotal / plantPower * 100 : null, 1, '%'),
    );
    fragment.append(heading);

    group.devices.forEach((device) => {
      const row = document.createElement('tr');
      const equipment = cell(displayName(device.deviceId), 'plant-efficiency-breakdown-equipment');
      const stateCell = document.createElement('td');
      const state = document.createElement('span');
      const running = device.state
        ? ['RUNNING', 'STARTING', 'STOPPING'].includes(device.state)
        : device.power >= fallbackRunningPowerKw;
      const standby = !running && device.power > 0;
      row.dataset.groupRow = group.key;
      if (!running) row.className = 'plant-efficiency-breakdown-idle';
      state.className = `plant-efficiency-breakdown-state ${running ? 'running' : standby ? 'standby' : 'off'}`;
      state.textContent = running ? 'Running' : standby ? 'Standby' : 'Off';
      stateCell.append(state);
      row.append(
        equipment,
        cell(device.type),
        stateCell,
        measurementCell(device.power, 1, ' kW'),
        measurementCell(validCoolingLoad ? device.power / coolingLoad : null, 4, ' kW/RT'),
        measurementCell(validPlantPower ? device.power / plantPower * 100 : null, 1, '%'),
      );
      fragment.append(row);
    });
  });

  const subtotalRow = document.createElement('tr');
  const subtotalLabel = cell('Submetered Equipment Subtotal');
  subtotalLabel.colSpan = 3;
  subtotalRow.className = 'plant-efficiency-breakdown-subtotal';
  subtotalRow.append(
    subtotalLabel,
    measurementCell(submeterPower, 1, ' kW'),
    measurementCell(validCoolingLoad ? submeterPower / coolingLoad : null, 4, ' kW/RT'),
    measurementCell(validPlantPower ? submeterPower / plantPower * 100 : null, 1, '%'),
  );
  fragment.append(subtotalRow);

  if (validPlantPower) {
    const unallocated = plantPower - submeterPower;
    const unallocatedRow = document.createElement('tr');
    unallocatedRow.className = 'plant-efficiency-breakdown-unallocated';
    unallocatedRow.append(
      cell('Unallocated / Estimated Auxiliary', 'plant-efficiency-breakdown-equipment'),
      cell('Main meter − submeters'),
      cell('Calculated'),
      measurementCell(unallocated, 1, ' kW'),
      measurementCell(validCoolingLoad ? unallocated / coolingLoad : null, 4, ' kW/RT'),
      measurementCell(unallocated / plantPower * 100, 1, '%'),
    );
    fragment.append(unallocatedRow);

    const totalRow = document.createElement('tr');
    const totalLabel = cell('Plant Total · Main Power Meter');
    totalLabel.colSpan = 3;
    totalRow.className = 'plant-efficiency-breakdown-total';
    totalRow.append(
      totalLabel,
      measurementCell(plantPower, 1, ' kW'),
      measurementCell(validCoolingLoad ? plantPower / coolingLoad : null, 4, ' kW/RT'),
      measurementCell(100, 1, '%'),
    );
    fragment.append(totalRow);
  }

  body.replaceChildren(fragment);
  foot.textContent = validPlantPower
    ? 'Plant efficiency uses the main power meter. Unallocated power is the aligned difference between the main meter and valid equipment submeters.'
    : 'Equipment power is available. Add plantPowerKw and coolingLoadRt to the query result to calculate plant-power share, kW/RT contribution, and unallocated auxiliary power.';

  if (root.dataset.collapseBound !== 'true') {
    root.dataset.collapseBound = 'true';
    root.addEventListener('click', (event) => {
      const toggle = event.target.closest('[data-group-toggle]');
      if (!toggle || !root.contains(toggle)) return;
      const expanded = toggle.getAttribute('aria-expanded') === 'true';
      toggle.setAttribute('aria-expanded', String(!expanded));
      root.querySelectorAll(`[data-group-row="${toggle.dataset.groupToggle}"]`).forEach((row) => {
        row.hidden = expanded;
      });
    });
  }
})();

