context.handlebars.registerHelper('deviceName', (deviceId) => {
  if (deviceId.startsWith('chiller')) return deviceId.replace('chiller', 'Chiller ');
  return deviceId.toUpperCase();
})

context.handlebars.registerHelper('divide', (a, b) => a / b);

context.handlebars.registerHelper('numberFormat', function (value, options) {
  // Helper parameters
  var dl = options.hash['decimalLength'] || 2;
  var ts = options.hash['thousandsSep'] || ',';
  var ds = options.hash['decimalSep'] || '.';

  // Parse to float
  var value = parseFloat(value);

  // The regex
  var re = '\\d(?=(\\d{3})+' + (dl > 0 ? '\\D' : '$') + ')';

  // Formats the number with the decimals
  var num = value.toFixed(Math.max(0, ~~dl));

  // Returns the formatted number
  return (ds ? num.replace('.', ds) : num).replace(new RegExp(re, 'g'), '$&' + ts);
});



// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
