options.afterRender:
(() => {
  const root = document.getElementById('plant-efficiency-kwh-breakdown');
  if (!root) return;
  const body = root.querySelector('tbody');
  const foot = root.querySelector('.plant-efficiency-breakdown-foot');
  const chartBar = root.querySelector('.plant-efficiency-breakdown-chart-bar');
  const chartLegend = root.querySelector('.plant-efficiency-breakdown-chart-legend');
  const chartNote = root.querySelector('.plant-efficiency-breakdown-chart-note');
  const coolingEnergyValue = root.querySelector('[data-cooling-energy]');
  const plantEfficiencyValue = root.querySelector('[data-plant-efficiency]');
  const source = typeof context !== 'undefined' && Array.isArray(context.data) ? context.data : [];
  const number = (value) => {
    if (value === null || value === undefined || value === '') return null;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  };
  const metadata = Array.isArray(source[0]) ? source[0][0] || {} : {};
  const plantEnergyKwh = number(metadata.plantEnergyKwh ?? metadata.plantPowerKw);
  const coolingEnergyRth = number(metadata.coolingEnergyRth ?? metadata.totalCoolingLoadRth);
  const validPlantEnergy = plantEnergyKwh !== null && plantEnergyKwh > 0;
  const validCoolingEnergy = coolingEnergyRth !== null && coolingEnergyRth > 0;
  const calculatedEfficiency = validPlantEnergy && validCoolingEnergy ? plantEnergyKwh / coolingEnergyRth : null;
  const plantEfficiency = number(metadata.plantEfficiencyKwhPerRth) ?? calculatedEfficiency;
  coolingEnergyValue.textContent = validCoolingEnergy ? coolingEnergyRth.toFixed(1) : '—';
  plantEfficiencyValue.textContent = plantEfficiency === null ? '—' : plantEfficiency.toFixed(3);
  const equipmentRows = Array.isArray(source[1]) ? source[1] : [];
  const devices = equipmentRows
    .filter((row) => row?.deviceId && row?.type && number(row?.energyKwh ?? row?.power) !== null)
    .map((row) => ({
      deviceId: String(row.deviceId),
      energyKwh: number(row.energyKwh ?? row.power),
      type: String(row.type),
      sortOrder: number(row.sortOrder) ?? 999,
    }));

  if (!devices.length) {
    const row = document.createElement('tr');
    const cell = document.createElement('td');
    row.className = 'plant-efficiency-breakdown-empty';
    cell.colSpan = 4;
    cell.textContent = 'No equipment energy data available.';
    row.append(cell);
    body.replaceChildren(row);
    chartNote.textContent = 'No energy data';
    chartBar.replaceChildren();
    chartLegend.replaceChildren();
    return;
  }

  const submeterEnergyKwh = devices.reduce((total, device) => total + device.energyKwh, 0);
  const typeNames = {
    chiller: 'Chillers',
    'cooling tower': 'Cooling Towers',
    chwp: 'Chilled-Water Pumps',
    cwp: 'Condenser-Water Pumps',
  };
  const typeColors = {
    chiller: '#4f9fe6',
    'cooling tower': '#9b7fea',
    chwp: '#2ec4b6',
    cwp: '#7088e8',
  };
  const fallbackColors = ['#4f9fe6', '#9b7fea', '#2ec4b6', '#7088e8', '#e59f3a'];
  const displayName = (deviceId) => {
    const match = deviceId.match(/^(chiller|ct|chwp|cwp)[-_ ]?(\d+)$/i);
    if (!match) return deviceId.toUpperCase();
    const prefix = match[1].toLowerCase() === 'chiller' ? 'CH' : match[1].toUpperCase();
    return `${prefix}-${match[2].padStart(2, '0')}`;
  };
  const groupKey = (type) => type.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const cell = (text, className) => {
    const node = document.createElement('td');
    if (className) node.className = className;
    node.textContent = text;
    return node;
  };
  const measurementCell = (value, digits, unit) => {
    if (value === null || !Number.isFinite(value)) return cell('—');
    const node = document.createElement('td');
    const reading = document.createElement('span');
    const suffix = document.createElement('span');
    reading.className = 'plant-efficiency-breakdown-value';
    suffix.className = 'plant-efficiency-breakdown-unit';
    reading.textContent = value.toFixed(digits);
    suffix.textContent = unit;
    node.append(reading, suffix);
    return node;
  };
  const groups = [...devices.reduce((map, device) => {
    const key = groupKey(device.type);
    const group = map.get(key) || {
      key,
      type: device.type,
      label: typeNames[device.type.toLowerCase()] || device.type,
      sortOrder: device.sortOrder,
      devices: [],
    };
    group.sortOrder = Math.min(group.sortOrder, device.sortOrder);
    group.devices.push(device);
    map.set(key, group);
    return map;
  }, new Map()).values()].sort((a, b) => a.sortOrder - b.sortOrder || a.label.localeCompare(b.label));
  groups.forEach((group, index) => {
    group.subtotal = group.devices.reduce((total, device) => total + device.energyKwh, 0);
    group.color = typeColors[group.type.toLowerCase()] || fallbackColors[index % fallbackColors.length];
  });

  const chartUsesMainMeter = validPlantEnergy && plantEnergyKwh >= submeterEnergyKwh;
  const chartTotal = chartUsesMainMeter ? plantEnergyKwh : submeterEnergyKwh;
  const chartItems = groups.map((group) => ({
    label: group.label,
    energyKwh: group.subtotal,
    color: group.color,
  }));
  if (chartUsesMainMeter && plantEnergyKwh > submeterEnergyKwh) {
    chartItems.push({
      label: 'Unallocated / Estimated Auxiliary',
      energyKwh: plantEnergyKwh - submeterEnergyKwh,
      color: '#b565a7',
    });
  }
  const chartDescription = chartItems
    .filter((item) => item.energyKwh > 0)
    .map((item) => `${item.label} ${(item.energyKwh / chartTotal * 100).toFixed(1)}%`)
    .join(', ');
  const chartSegments = document.createDocumentFragment();
  const legendItems = document.createDocumentFragment();
  chartItems.forEach((item) => {
    const share = chartTotal > 0 ? item.energyKwh / chartTotal * 100 : 0;
    if (item.energyKwh > 0) {
      const segment = document.createElement('span');
      segment.className = 'plant-efficiency-breakdown-chart-segment';
      segment.style.width = `${share}%`;
      segment.style.backgroundColor = item.color;
      segment.title = `${item.label}: ${item.energyKwh.toFixed(1)} kWh (${share.toFixed(1)}%)`;
      chartSegments.append(segment);
    }
    const legendItem = document.createElement('span');
    const swatch = document.createElement('span');
    const label = document.createElement('span');
    legendItem.className = 'plant-efficiency-breakdown-chart-legend-item';
    swatch.className = 'plant-efficiency-breakdown-chart-swatch';
    swatch.style.backgroundColor = item.color;
    label.textContent = `${item.label} · ${item.energyKwh.toFixed(1)} kWh · ${share.toFixed(1)}%`;
    legendItem.append(swatch, label);
    legendItems.append(legendItem);
  });
  chartBar.replaceChildren(chartSegments);
  chartBar.setAttribute('aria-label', `Energy usage breakdown: ${chartDescription}`);
  chartLegend.replaceChildren(legendItems);
  chartNote.textContent = chartUsesMainMeter
    ? 'Share of main plant energy'
    : 'Share of submetered energy';

  const fragment = document.createDocumentFragment();
  groups.forEach((group) => {
    group.devices.sort((a, b) => a.deviceId.localeCompare(b.deviceId, undefined, { numeric: true }));
    const heading = document.createElement('tr');
    const labelCell = document.createElement('td');
    const toggle = document.createElement('button');
    heading.className = 'plant-efficiency-breakdown-group';
    labelCell.colSpan = 2;
    toggle.className = 'plant-efficiency-breakdown-toggle';
    toggle.type = 'button';
    toggle.dataset.groupToggle = group.key;
    toggle.setAttribute('aria-expanded', 'true');
    toggle.textContent = group.label;
    labelCell.append(toggle);
    heading.append(
      labelCell,
      measurementCell(group.subtotal, 1, ' kWh'),
      measurementCell(validPlantEnergy ? group.subtotal / plantEnergyKwh * 100 : null, 1, '%'),
    );
    fragment.append(heading);

    group.devices.forEach((device) => {
      const row = document.createElement('tr');
      row.dataset.groupRow = group.key;
      row.append(
        cell(displayName(device.deviceId), 'plant-efficiency-breakdown-equipment'),
        cell(device.type),
        measurementCell(device.energyKwh, 1, ' kWh'),
        measurementCell(validPlantEnergy ? device.energyKwh / plantEnergyKwh * 100 : null, 1, '%'),
      );
      fragment.append(row);
    });
  });

  const subtotalRow = document.createElement('tr');
  const subtotalLabel = cell('Submetered Equipment Subtotal');
  subtotalLabel.colSpan = 2;
  subtotalRow.className = 'plant-efficiency-breakdown-subtotal';
  subtotalRow.append(
    subtotalLabel,
    measurementCell(submeterEnergyKwh, 1, ' kWh'),
    measurementCell(validPlantEnergy ? submeterEnergyKwh / plantEnergyKwh * 100 : null, 1, '%'),
  );
  fragment.append(subtotalRow);

  if (validPlantEnergy) {
    const unallocatedEnergyKwh = plantEnergyKwh - submeterEnergyKwh;
    const unallocatedRow = document.createElement('tr');
    unallocatedRow.className = 'plant-efficiency-breakdown-unallocated';
    unallocatedRow.append(
      cell('Unallocated / Estimated Auxiliary', 'plant-efficiency-breakdown-equipment'),
      cell('Main meter − submeters'),
      measurementCell(unallocatedEnergyKwh, 1, ' kWh'),
      measurementCell(unallocatedEnergyKwh / plantEnergyKwh * 100, 1, '%'),
    );
    fragment.append(unallocatedRow);

    const totalRow = document.createElement('tr');
    const totalLabel = cell('Plant Total · Main Energy Meter');
    totalLabel.colSpan = 2;
    totalRow.className = 'plant-efficiency-breakdown-total';
    totalRow.append(
      totalLabel,
      measurementCell(plantEnergyKwh, 1, ' kWh'),
      measurementCell(100, 1, '%'),
    );
    fragment.append(totalRow);
  }

  body.replaceChildren(fragment);
  foot.textContent = validPlantEnergy
    ? 'Energy reconciliation uses aligned main-meter and equipment-submeter usage over the selected time range. Unallocated energy may include auxiliary loads, distribution losses, and meter variance.'
    : 'Equipment energy is available. Add plantEnergyKwh to the query result to calculate main-meter share and unallocated auxiliary energy.';

  if (root.dataset.collapseBound !== 'true') {
    root.dataset.collapseBound = 'true';
    root.addEventListener('click', (event) => {
      const toggle = event.target.closest('[data-group-toggle]');
      if (!toggle || !root.contains(toggle)) return;
      const expanded = toggle.getAttribute('aria-expanded') === 'true';
      toggle.setAttribute('aria-expanded', String(!expanded));
      root.querySelectorAll(`[data-group-row="${toggle.dataset.groupToggle}"]`).forEach((row) => {
        row.hidden = expanded;
      });
    });
  }
})();

options.helpers:
// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

