options.helpers:
function calcWetBulb(t, rh) {
  if (t == null || rh == null) return null;

  const tw = t * Math.atan(0.151977 * Math.pow(rh + 8.313659, 0.5))
    + Math.atan(t + rh)
    - Math.atan(rh - 1.676331)
    + 0.00391838 * Math.pow(rh, 1.5) * Math.atan(0.023101 * rh)
    - 4.686035;

  return tw;
}

function estimateOutdoorWeather(outdoorTempC, rhPercent, solarWm2) {
  if (!Number.isFinite(outdoorTempC) || !Number.isFinite(rhPercent) || !Number.isFinite(solarWm2)) {
    // throw new TypeError('Outdoor temperature, RH, and solar irradiance must be finite numbers.');
    console.error('Outdoor temperature, RH, and solar irradiance must be finite numbers.');
    return null;
  }
  if (rhPercent < 0 || rhPercent > 100 || solarWm2 < 0) {
    // throw new RangeError('RH must be 0-100% and solar irradiance must be non-negative.');
    console.error('RH must be 0-100% and solar irradiance must be non-negative.');
    return null;
  }

  const wetBulbC = calcWetBulb(outdoorTempC, rhPercent);
  const wetBulbDepressionC = outdoorTempC - wetBulbC;

  if (solarWm2 < 20) {
    return { wetBulbC, condition: 'Night', iconClass: 'fa-moon-o' };
  }
  if (solarWm2 < 150 && rhPercent >= 85 && wetBulbDepressionC <= 2) {
    return { wetBulbC, condition: 'Humid overcast', iconClass: 'fa-tint' };
  }
  if (solarWm2 < 250) {
    return { wetBulbC, condition: 'Cloudy', iconClass: 'fa-cloud' };
  }
  if (solarWm2 < 650) {
    return { wetBulbC, condition: 'Partly cloudy', iconClass: 'fa-cloud' };
  }
  if (wetBulbDepressionC > 4) {
    return { wetBulbC, condition: 'Sunny', iconClass: 'fa-sun-o' };
  }
  return { wetBulbC, condition: 'Bright and humid', iconClass: 'fa-sun-o' };
}

context.handlebars.registerHelper('plantEfficiencyStatus', (kwPerRt) => {
  if (kwPerRt <= 0.65) return 'good';
  if (kwPerRt <= 0.75) return 'normal';
  if (kwPerRt <= 0.85) return 'warn';
  return 'bad';
})


context.handlebars.registerHelper('wetBulb', calcWetBulb);
context.handlebars.registerHelper('outdoorWeather', estimateOutdoorWeather);

context.handlebars.registerHelper('demandDateTime', function (value) {
  if (value == null) return '--';

  const timestamp = new Date(value);
  if (Number.isNaN(timestamp.getTime())) return '--';

  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Kuala_Lumpur',
    day: '2-digit',
    month: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(timestamp);
});

context.handlebars.registerHelper('numberFormat', function (value, options) {
  if (value == null) return '---';

  // Helper parameters
  var dl = options.hash['decimalLength'] || 0;
  var ts = options.hash['thousandsSep'] || ',';
  var ds = options.hash['decimalSep'] || '.';

  // Parse to float
  var value = parseFloat(value);

  // The regex
  var re = '\\d(?=(\\d{3})+' + (dl > 0 ? '\\D' : '$') + ')';

  // Formats the number with the decimals
  var num = value.toFixed(Math.max(0, ~~dl));

  // Returns the formatted number
  return (ds ? num.replace('.', ds) : num).replace(new RegExp(re, 'g'), '$&' + ts);
});



// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

