context.handlebars.registerHelper("controlMode", (mode) => {
  return mode == 1 ? 'auto' : 'manual';
})

// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

options.styles:
.plant-ct-card {
  width: 100%;
  box-sizing: border-box;
  font-family: var(--font-sans, Inter, Arial, sans-serif);
  color: var(--color-text-primary, #1f2933);
  background: #ffffff;
  border: 1px solid #d0d5dd;
  border-radius: 6px;
  padding: 13px;
}
.plant-ct-card.running {
  background: #ecf8e8;
  border-color: #7fb069;
  border-left: 5px solid #548235;
  box-shadow: 0 0 0 1px rgba(84, 130, 53, 0.1);
}
.plant-ct-card.stopped {
  background: #fafafa;
  border-color: #e5e7eb;
}
.plant-ct-card.tripped,
.plant-ct-card.fault {
  background: #fff5f5;
  border-color: #f2b8b5;
}
.plant-ct-card.unavailable {
  background: #f8f9fa;
  border-color: #d0d5dd;
  opacity: 0.78;
}
.plant-ct-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 13px;
}
.plant-ct-title {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.plant-ct-name {
  font-size: 17px;
  font-weight: 700;
}
.plant-ct-badge {
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.3px;
  padding: 4px 9px;
  text-transform: uppercase;
  white-space: nowrap;
}
.plant-ct-badge.lead {
  background: #dcfce7;
  color: #166534;
}
.plant-ct-badge.lag {
  background: #dbeafe;
  color: #1d4ed8;
}
.plant-ct-badge.standby {
  background: #f2f4f7;
  color: #667085;
}
.plant-ct-badge.available {
  background: #eaf7e4;
  color: #548235;
}
.plant-ct-badge.maintenance {
  background: #fef3c7;
  color: #92400e;
}
.plant-ct-badge.disabled {
  background: #fee2e2;
  color: #991b1b;
}
.plant-ct-mode {
  display: inline-block;
  border-radius: 999px;
  padding: 3px 9px;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
}
.plant-ct-mode.auto {
  background: #dcfce7;
  color: #166534;
}
.plant-ct-mode.manual {
  background: #fef3c7;
  color: #92400e;
}
.plant-ct-state {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  white-space: nowrap;
}
.plant-ct-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #548235;
}
.plant-ct-card.running .plant-ct-state {
  color: #548235;
}
.plant-ct-card.idle .plant-ct-dot {
  background: #98a2b3;
}
.plant-ct-card.idle .plant-ct-state {
  color: #667085;
}
.plant-ct-card.tripped .plant-ct-dot,
.plant-ct-card.fault .plant-ct-dot {
  background: #c00000;
}
.plant-ct-card.tripped .plant-ct-state,
.plant-ct-card.fault .plant-ct-state {
  color: #c00000;
}
.plant-ct-card.unavailable .plant-ct-dot {
  background: #667085;
}
.plant-ct-card.unavailable .plant-ct-state {
  color: #667085;
}
.plant-ct-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.plant-ct-metric {
  min-width: 0;
  border-top: 1px solid rgba(84, 130, 53, 0.16);
  padding-top: 8px;
}
.plant-ct-label {
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.3px;
  overflow: hidden;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}
.plant-ct-value {
  margin-top: 3px;
  font-size: 18px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.plant-ct-unit {
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  font-weight: 400;
}
.plant-ct-ok {
  color: #548235;
}
.plant-ct-warn {
  color: #bf8f00;
}
.plant-ct-bad {
  color: #c00000;
}
@media (max-width: 360px) {
  .plant-ct-grid {
    grid-template-columns: 1fr;
  }
}

/* ---------- Dark theme (only applies when Grafana is in dark mode) ---------- */
.plant-ct-card:where(.dark) { color: var(--color-text-primary, #e4e4ec); background: #181b1f; border-color: #34373d; }
.plant-ct-card:where(.dark).running { background: rgba(115, 191, 105, 0.16); border-color: rgba(115, 191, 105, 0.45); border-left-color: #73bf69; box-shadow: 0 0 0 1px rgba(115, 191, 105, 0.16); }
.plant-ct-card:where(.dark).stopped,
.plant-ct-card:where(.dark).idle { background: #181b1f; border-color: #2a2d33; }
.plant-ct-card:where(.dark).tripped,
.plant-ct-card:where(.dark).fault { background: #181b1f; border-color: rgba(242, 73, 92, 0.45); }
.plant-ct-card:where(.dark).unavailable { background: #181b1f; border-color: #34373d; }
*:where(.plant-ct-card.dark) .plant-ct-badge.lead,
*:where(.plant-ct-card.dark) .plant-ct-badge.available,
*:where(.plant-ct-card.dark) .plant-ct-mode.auto { background: rgba(115, 191, 105, 0.16); color: #73bf69; }
*:where(.plant-ct-card.dark) .plant-ct-badge.lag,
*:where(.plant-ct-card.dark) .plant-ct-pump-badge { background: rgba(87, 148, 242, 0.16); color: #8ab8ff; }
*:where(.plant-ct-card.dark) .plant-ct-badge.standby { background: #22252b; color: #b0b0be; }
*:where(.plant-ct-card.dark) .plant-ct-badge.maintenance,
*:where(.plant-ct-card.dark) .plant-ct-mode.manual { background: rgba(242, 204, 12, 0.16); color: #ff9830; }
*:where(.plant-ct-card.dark) .plant-ct-badge.disabled { background: rgba(242, 73, 92, 0.16); color: #ff7383; }
.plant-ct-card:where(.dark).running .plant-ct-state { color: #73bf69; }
.plant-ct-card:where(.dark).idle .plant-ct-state,
.plant-ct-card:where(.dark).stopped .plant-ct-state,
.plant-ct-card:where(.dark).unavailable .plant-ct-state { color: #b0b0be; }
.plant-ct-card:where(.dark).tripped .plant-ct-state,
.plant-ct-card:where(.dark).fault .plant-ct-state { color: #ff7383; }
*:where(.plant-ct-card.dark) .plant-ct-metric { border-color: rgba(115, 191, 105, 0.26); }
*:where(.plant-ct-card.dark) .plant-ct-label,
*:where(.plant-ct-card.dark) .plant-ct-unit,
*:where(.plant-ct-card.dark) .plant-ct-interval { color: var(--color-text-secondary, #b0b0be); }
*:where(.plant-ct-card.dark) .plant-ct-good,
*:where(.plant-ct-card.dark) .plant-ct-ok { color: #73bf69; }
*:where(.plant-ct-card.dark) .plant-ct-warn { color: #f2cc0c; }
*:where(.plant-ct-card.dark) .plant-ct-bad { color: #ff7383; }

.plant-ct-card:where(.dark).running .plant-ct-dot { background: #73bf69; }
.plant-ct-card:where(.dark).idle .plant-ct-dot,
.plant-ct-card:where(.dark).stopped .plant-ct-dot,
.plant-ct-card:where(.dark).unavailable .plant-ct-dot { background: #7f8490; }
.plant-ct-card:where(.dark).tripped .plant-ct-dot,
.plant-ct-card:where(.dark).fault .plant-ct-dot { background: #ff7383; }
